            parts = listOf(
                StoryPart(1, "The Clock That Stopped", listOf("When Nia returned to Greyhaven for the school holidays, the lighthouse clock had stopped at 8:17. The town said it had been broken for years, yet every evening the beam still swept across the harbour.", "Her grandfather had once kept the lighthouse. Before he passed away, he left her a brass key and one instruction: never turn it while the light is shining.", "That night, a folded note appeared beneath her bedroom door. It contained only a time: 8:17 tomorrow.")),
                StoryPart(2, "A Map in the Margin", listOf("Nia showed the note to her friend Tobi, who loved puzzles more than sensible explanations. Together they examined the lighthouse visitor book and found her grandfather's handwriting beside the same time.", "A tiny map had been drawn in the margin. It led from the lighthouse to the old signal station on the headland.", "At the bottom was a warning: the tide would reveal the path, but only for twenty minutes.")),
                StoryPart(3, "The Signal Station", listOf("They reached the station at low tide and found its door unlocked. Dust covered the instruments, except for one brass lever polished by recent use.", "Tobi discovered a drawer containing postcards addressed to people who had left Greyhaven decades earlier. Each card carried the same lighthouse symbol.", "Before they could read them all, the beam outside flashed twice, paused, then flashed once. Someone was signalling back.")),
                StoryPart(4, "The Keeper's Code", listOf("Nia recognised the pattern from her grandfather's old notebooks. It was not a distress signal but a simple code for letters.", "The message spelled out a name: Amara Vale. The town archive listed Amara as the first woman to design Greyhaven's harbour wall, though her work had been credited to someone else.", "A second clue pointed to the clock mechanism. Nia realised the stopped time was not an accident; it marked the day Amara's plans vanished.")),
                StoryPart(5, "The Missing Plans", listOf("The archive's curator, Mr Bell, listened carefully and opened a locked cabinet. Inside lay a record of the harbour project, with several pages carefully removed.", "He admitted that his predecessor had hidden the original plans after a dispute over recognition. The town had repeated the wrong story for generations.", "Mr Bell gave Nia a sealed envelope her grandfather had entrusted to the archive. It was addressed to Amara's granddaughter.")),
                StoryPart(6, "A Letter Across Generations", listOf("The envelope contained an apology and a list of addresses. Amara's family had moved inland, believing Greyhaven had forgotten her completely.", "Nia and Tobi traced the family to a small bookshop. The owner, Leila, was surprised to learn that the town still had evidence of her grandmother's work.", "Leila agreed to return with them, but asked one question: why had the lighthouse keeper waited so long?")),
                StoryPart(7, "The Keeper's Promise", listOf("Nia read her grandfather's final letter. He had discovered the truth late in life, but the archive board refused to correct the record without the original signed drawings.", "He had spent years searching for those drawings and finally found them behind the clock face. The brass key was meant to open the clock's hidden panel.", "Nia held the key up to the light. For the first time, she understood why he had told her not to turn it while the beam was shining.")),
                StoryPart(8, "Behind the Clock", listOf("At dusk, Nia waited until the lighthouse beam passed the harbour, then turned the key. A narrow panel opened behind the clockwork.", "Inside was a waterproof tube containing Amara's signed plans, a photograph of the original construction team, and a note from Nia's grandfather.", "The note asked her to bring the documents into daylight, not keep them as a private discovery. The truth belonged to the whole town.")),
